// wrote nothing.
func (o *observedSessionRepository) created(ctx context.Context, m, out *eventpbv1.Session) {
	switch {
	case out.GetName() != "":
		o.changes.Changed(ctx, out.GetName())
	case m.GetName() != "":
		o.changes.Changed(ctx, m.GetName())
	}
}

func (o *observedSessionRepository) Update(ctx context.Context, m *eventpbv1.Session, paths []string) (*eventpbv1.Session, error) {
	out, err := o.SessionRepository.Update(ctx, m, paths)
	o.changes.Changed(ctx, m.GetName())
	return out, err
}

