// guardedEventRepository keeps Event's references whole; see guard.
type guardedEventRepository struct {
	EventRepository
	refs *repox.References
}

func (g *guardedEventRepository) Create(ctx context.Context, parent string, m *eventpbv1.Event) (*eventpbv1.Event, error) {
	if err := resolveEventReferences(ctx, g.refs, m, nil); err != nil {
		return nil, err
	}
	return g.EventRepository.Create(ctx, parent, m)
}

func (g *guardedEventRepository) Update(ctx context.Context, m *eventpbv1.Event, paths []string) (*eventpbv1.Event, error) {
	if err := resolveEventReferences(ctx, g.refs, m, paths); err != nil {
		return nil, err
	}
	return g.EventRepository.Update(ctx, m, paths)
}

func (g *guardedEventRepository) UpdateWithOutputOnly(ctx context.Context, m *eventpbv1.Event, paths, outputPaths []string) (*eventpbv1.Event, error) {
	if err := resolveEventReferences(ctx, g.refs, m, paths); err != nil {
		return nil, err
	}
	return g.EventRepository.UpdateWithOutputOnly(ctx, m, paths, outputPaths)
}

func (g *guardedEventRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "aperio.event.v1/Event", name)
	if err != nil {
		return err
	}
	if err := g.EventRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, true)
	return nil
}

// resolveEventReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveEventReferences(ctx context.Context, refs *repox.References, m *eventpbv1.Event, paths []string) error {
	if refs == nil {
		return nil
	}
	if repox.InMask(paths, "coordinator") {
		if err := refs.Resolve(ctx, "coordinator", "users.shokki.engineering/User", m.GetCoordinator()); err != nil {
			return err
		}
	}
	return nil
}

// queueEventReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueEventReferences(u *repox.Unit, m *eventpbv1.Event, paths []string) {
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error { return resolveEventReferences(ctx, refs, m, paths) })
	}
}

// queueEventDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueEventDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "aperio.event.v1/Event", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

